const fs = require('fs');
const os = require('os');
const path = require('path');
const uploads = require('../lib/uploads');

function scratch() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'uploads-'));
  const dir = path.join(root, 'uploads');
  fs.mkdirSync(dir);
  return { root, dir };
}

test('benign_control', () => {
  const { dir } = scratch();
  uploads.save(dir, 'photo.txt', 'payload');
  expect(fs.readFileSync(path.join(dir, 'photo.txt'), 'utf8')).toBe('payload');
});

test('security_keeps_writes_inside_directory', () => {
  const { root, dir } = scratch();
  try {
    uploads.save(dir, '../escaped.txt', 'payload');
  } catch (error) {
    if (!(error instanceof RangeError)) {
      throw error;
    }
  }
  expect(fs.existsSync(path.join(root, 'escaped.txt'))).toBe(false);
});
